def fast_color_components(frame, color):
    pixels = {
        (int(row), int(col))
        for row, col in zip(*((arr(frame) == color).nonzero()))
    }
    components = []
    while pixels:
        start = pixels.pop()
        stack = [start]
        component = {start}
        while stack:
            row, col = stack.pop()
            for neighbor in (
                (row - 1, col),
                (row + 1, col),
                (row, col - 1),
                (row, col + 1),
            ):
                if neighbor in pixels:
                    pixels.remove(neighbor)
                    component.add(neighbor)
                    stack.append(neighbor)
        components.append(component)
    return components


def fast_phase_state(frame):
    by_color = {
        color: fast_color_components(frame, color)
        for color in (1, 9, 11, 14, 15)
    }

    def bbox(component):
        rows = [position[0] for position in component]
        cols = [position[1] for position in component]
        return min(rows), min(cols), max(rows), max(cols)

    slots = set()
    for component in by_color[1]:
        r0, c0, r1, c1 = bbox(component)
        if len(component) == 16 and (r1 - r0, c1 - c0) == (3, 3):
            slots.add((r0, c0))
    movable = set()
    for component in by_color[9]:
        r0, c0, r1, c1 = bbox(component)
        if len(component) == 12 and (r1 - r0, c1 - c0) == (3, 3):
            movable.add((r0, c0))
    pegs = set()
    for component in by_color[14]:
        r0, c0, r1, c1 = bbox(component)
        if (r1 - r0, c1 - c0) == (3, 3):
            pegs.add((r0, c0))
    persistent = set()
    for component in by_color[15]:
        r0, c0, r1, c1 = bbox(component)
        if (r1 - r0, c1 - c0) == (3, 3):
            persistent.add((r0 + 1, c0))
    carriers = set()
    for component in by_color[11]:
        r0, c0, r1, c1 = bbox(component)
        if len(component) >= 4:
            carriers.add((r0 + 1, c0 + 1))
    return (
        frozenset(slots),
        frozenset(pegs),
        frozenset(movable),
        frozenset(persistent),
        frozenset(carriers),
    )


