def phase_two_search(env, max_states=3000, max_cost=28):
    root = env.clone()

    root = env.clone()
    phase_one = symbolic_bridge_solution(root.frame())
    play_symbolic_path(root, phase_one["path"])
    base_level = int(root.levels_completed)

    def reconstruct(path):
        node = root.clone()
        for action in path:
            if isinstance(action, tuple):
                node.step(*action)
            else:
                node.step(action)
        return node

